var e=class{apiBase;sessions;constructor(e,t){this.apiBase=e,this.sessions=t}login(e){return this.submit(`/auth/login`,e)}register(e){return this.submit(`/auth/register`,e)}async submit(e,t){let n=await fetch(`${this.apiBase}${e}`,{method:`POST`,headers:{"content-type":`application/json`},body:JSON.stringify(t)});if(!(n.headers.get(`content-type`)??``).includes(`application/json`))throw Error(`HTTP_${n.status}`);let r=await n.json();if(!n.ok||!r.data)throw Error(r.code||`HTTP_${n.status}`);return await this.sessions.setTokens(r.data.access_token,r.data.refresh_token),r.data}};export{e as t};